//! Generation of Snakemake rules from a study's configuration, and the `Snakefile` stub.

use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};

use super::PipelineError;
use super::config::StageInput;
use super::provenance::{RECORD_FILE, ResolvedStage};
use super::summary::read_study;
use crate::study::{STUDIES_DIR, Status};

// rq-3c19a18d rq-fbc524b4
/// The exact `Snakefile` stub of a study.
pub fn stub(study: &str) -> String {
    format!(
        "# Generated by tophat for study {study}. Do not edit: `tophat check` rejects changes.
# The rules are regenerated from config/ every time Snakemake starts.
import subprocess
from pathlib import Path

_rules = Path(workflow.basedir).parents[1] / \".tophat\" / \"generated\" / \"{study}.smk\"
subprocess.run([\"tophat\", \"pipeline\", \"rules\", \"{study}\", \"--output\", str(_rules)], check=True)
include: str(_rules)


rule tophat_default:
    default_target: True
    input: _TOPHAT_DEFAULT_INPUTS
    run:
        _tophat_default()
"
    )
}

/// A Python string literal.
fn py(s: &str) -> String {
    serde_json::to_string(s).expect("strings serialize")
}

/// A Python string literal for a Snakemake input or output pattern: braces are escaped so they are
/// not taken for wildcards.
fn pattern(path: &Path) -> String {
    py(&path
        .display()
        .to_string()
        .replace('{', "{{")
        .replace('}', "}}"))
}

/// A Snakemake rule name for a stage job: hyphens become underscores.
fn rule_name(stage: &str, key: &str, trial: bool) -> String {
    let hex = key.trim_start_matches("sk-");
    let base = format!("{}_{hex}", stage.replace('-', "_"));
    if trial { format!("trial_{base}") } else { base }
}

/// The target rule name of a variant.
pub fn variant_target(variant: &str, trial: bool) -> String {
    let v = variant.replace('-', "_");
    if trial {
        format!("trial_{v}")
    } else {
        format!("variant_{v}")
    }
}

/// Where a fan-out stage's items come from.
enum ItemSource {
    /// An upstream stage, which becomes a checkpoint.
    Checkpoint { rule: String, dir: PathBuf },
    /// A dataset's top-level files, known now.
    Static(Vec<String>),
}

/// One stage job: a distinct (stage, key).
struct Job {
    stage: String,
    key: String,
    variant: String,
    out_dir: PathBuf,
    threads: u32,
    inputs: Vec<PathBuf>,
    qc: Vec<(String, String, String)>,
    fan_out: Option<ItemSource>,
    external: bool,
}

const HELPERS: &str = r#"import json as _tophat_json
import os as _tophat_os
import subprocess as _tophat_subprocess


def _tophat(*args):
    _tophat_subprocess.run(["tophat", *args], check=True)


def _tophat_items(directory):
    names = set()
    for name in _tophat_os.listdir(directory):
        path = _tophat_os.path.join(directory, name)
        if name == "provenance.json" or name.startswith(".") or not _tophat_os.path.isfile(path):
            continue
        stem, dot, _ = name.rpartition(".")
        names.add(stem if dot and stem else name)
    return sorted(names)


def _tophat_checkpoint_items(upstream, directory):
    upstream.get()
    return _tophat_items(directory)


def _tophat_job(stage, key, variant, item=None, trial=False, qc=(), external=False):
    for qc_stage, qc_key, qc_variant in qc:
        status = _tophat_subprocess.run(
            ["tophat", "stage", "qc-status", _TOPHAT_STUDY, qc_stage, "--key", qc_key]
        )
        verdict = "studies/" + _TOPHAT_STUDY + "/qc/" + qc_stage + "/" + qc_key + ".md"
        if status.returncode == 1:
            raise ValueError("QC verdict for stage " + qc_stage + " is 'fail' (" + verdict + "); nothing downstream runs")
        if status.returncode != 0:
            raise ValueError(
                "QC verdict needed before stages that use `" + qc_stage + "` can run: run `tophat stage qc "
                + _TOPHAT_STUDY + " " + qc_stage + " --variant " + qc_variant + "`"
            )
    extra = (["--item", item] if item else []) + (["--trial"] if trial else [])
    if external:
        status = _tophat_subprocess.run(
            ["tophat", "stage", "external", _TOPHAT_STUDY, stage, "--key", key, "--variant", variant, *extra]
        )
        if status.returncode == 3:
            raise ValueError(
                "External job for stage " + stage + " is waiting for you: follow the steps above, then run the pipeline again"
            )
        if status.returncode != 0:
            raise ValueError("The returned job folder of stage " + stage + " cannot be ingested (see above)")
        return
    begun = _tophat_json.loads(
        _tophat_subprocess.run(
            ["tophat", "stage", "begin", _TOPHAT_STUDY, stage, "--key", key, "--variant", variant, *extra],
            check=True,
            stdout=_tophat_subprocess.PIPE,
            text=True,
        ).stdout
    )
    pixi = (
        ["pixi", "run", "--frozen"]
        + (["--manifest-path", begun["manifest"]] if begun.get("manifest") else [])
        + ["-e", begun["env"], "--", "sh", "-c"]
    )
    _tophat_subprocess.run(pixi + [begun["run"]], cwd=begun["cwd"], check=True)
    if begun.get("validate"):
        if _tophat_subprocess.run(pixi + [begun["validate"]], cwd=begun["cwd"]).returncode != 0:
            raise ValueError(
                "Validation of stage " + stage + " failed (see above); its output is not sealed"
            )
    _tophat("stage", "seal", _TOPHAT_STUDY, stage, "--key", key, "--variant", variant, *extra)
"#;

/// Checks that a referenced dataset can be read on this machine.
fn check_dataset(
    resolved: &ResolvedStage,
    r: &crate::data::DatasetRef,
) -> Result<PathBuf, PipelineError> {
    let m = resolved
        .ctx
        .manifest(r)
        .ok_or_else(|| PipelineError::Data(format!("dataset `{r}` does not exist")))?;
    if m.retired.is_some() {
        return Err(PipelineError::Data(format!("dataset `{r}` is retired")));
    }
    let location = resolved.roots.location(&m.root).ok_or_else(|| {
        PipelineError::Data(format!(
            "dataset `{r}` is in root `{}`, which is not configured on this machine",
            m.root
        ))
    })?;
    let dir = crate::fsutil::join_rel(location, &m.path);
    for f in &m.files {
        let ok = std::fs::metadata(crate::fsutil::join_rel(&dir, &f.path))
            .is_ok_and(|meta| meta.is_file() && meta.len() == f.size);
        if !ok {
            return Err(PipelineError::Data(format!(
                "dataset `{r}`: file `{}` is missing or has changed",
                f.path
            )));
        }
    }
    Ok(dir)
}

// rq-aa6553ad rq-56d46fa3 rq-5782f3d0 rq-a44c3b76 rq-bdfef246
/// Generates the Snakemake rules file of a study.
pub fn generate_rules(root: &Path, study: &str) -> Result<String, PipelineError> {
    let doc = read_study(root, study)?;
    let trial = doc.status() == Some(Status::Draft);
    let variants = doc.variants().to_vec();
    if variants.is_empty() {
        return Err(PipelineError::Study(format!(
            "study `{study}` lists no variants"
        )));
    }

    let mut jobs: Vec<Job> = Vec::new();
    let mut job_index: BTreeMap<(String, String), usize> = BTreeMap::new();
    let mut checkpoints: BTreeSet<(String, String)> = BTreeSet::new();
    let mut variant_records: Vec<(String, Vec<PathBuf>, Vec<PathBuf>)> = Vec::new();

    for variant in &variants {
        let resolved = ResolvedStage::load_mode(root, study, variant, None, trial)?;
        let mut all = Vec::new();
        let mut results = Vec::new();
        for stage in &resolved.config.stages {
            let key = resolved.key(&stage.name).to_string();
            let out_dir = resolved.out_dir(&stage.name, trial)?;
            let record = out_dir.join(RECORD_FILE);
            all.push(record.clone());
            if stage.result.is_some() {
                results.push(record);
            }
            if job_index.contains_key(&(stage.name.clone(), key.clone())) {
                continue;
            }
            let mut inputs = Vec::new();
            let mut qc = Vec::new();
            for input in stage.inputs.values() {
                match input {
                    StageInput::Stage(upstream) => {
                        let upstream_key = resolved.key(upstream).to_string();
                        inputs.push(resolved.out_dir(upstream, trial)?.join(RECORD_FILE));
                        if !trial && resolved.config.is_gated(upstream) {
                            qc.push((upstream.clone(), upstream_key, variant.clone()));
                        }
                    }
                    StageInput::Dataset(r) => {
                        check_dataset(&resolved, r)?;
                    }
                }
            }
            let fan_out = match stage.foreach.as_ref().map(|f| &stage.inputs[f]) {
                None => None,
                Some(StageInput::Stage(upstream)) => {
                    let upstream_key = resolved.key(upstream).to_string();
                    checkpoints.insert((upstream.clone(), upstream_key.clone()));
                    Some(ItemSource::Checkpoint {
                        rule: rule_name(upstream, &upstream_key, trial),
                        dir: resolved.out_dir(upstream, trial)?,
                    })
                }
                Some(StageInput::Dataset(r)) => {
                    let m = resolved.ctx.manifest(r).expect("checked above");
                    let mut names: Vec<String> = m
                        .files
                        .iter()
                        .filter(|f| {
                            !f.path.contains('/')
                                && !f.path.starts_with('.')
                                && f.path != RECORD_FILE
                        })
                        .map(|f| match f.path.rsplit_once('.') {
                            Some((stem, _)) if !stem.is_empty() => stem.to_string(),
                            _ => f.path.clone(),
                        })
                        .collect();
                    names.sort();
                    names.dedup();
                    Some(ItemSource::Static(names))
                }
            };
            job_index.insert((stage.name.clone(), key.clone()), jobs.len());
            jobs.push(Job {
                stage: stage.name.clone(),
                key,
                variant: variant.clone(),
                out_dir,
                threads: stage.threads,
                inputs,
                qc,
                fan_out,
                external: stage.external.is_some(),
            });
        }
        variant_records.push((variant.clone(), all, results));
    }

    let mut out = format!(
        "# Generated by tophat {} for study {study}. Do not edit: regenerated from config/ on every run.\n{HELPERS}\n_TOPHAT_STUDY = {}\n\n",
        env!("CARGO_PKG_VERSION"),
        py(study)
    );
    let list = |paths: &[PathBuf]| {
        paths
            .iter()
            .map(|p| format!("        {},\n", pattern(p)))
            .collect::<String>()
    };

    // Targets. An included file cannot set Snakemake's default target, so the stub's
    // `tophat_default` rule takes its inputs and action from `_TOPHAT_DEFAULT_INPUTS` and
    // `_tophat_default`: the summary normally, every trial output and `EXPLORATION.md` for a draft.
    // rq-2e420949
    if trial {
        let all: Vec<PathBuf> = variant_records
            .iter()
            .flat_map(|(_, all, _)| all.clone())
            .collect();
        out.push_str(&format!(
            "_TOPHAT_DEFAULT_INPUTS = [\n{}]\n\n\ndef _tophat_default():\n    _tophat(\"study\", \"exploration\", _TOPHAT_STUDY)\n\n\nrule trial:\n    input:\n{}    run:\n        _tophat_default()\n\n",
            list(&all).replace("        ", "    "),
            list(&all)
        ));
    } else {
        let results: Vec<PathBuf> = variant_records
            .iter()
            .flat_map(|(_, _, r)| r.clone())
            .collect();
        out.push_str(&format!(
            "_TOPHAT_DEFAULT_INPUTS = [\n{}]\n\n\ndef _tophat_default():\n    _tophat(\"study\", \"summarize\", _TOPHAT_STUDY)\n\n\nrule summary:\n    input:\n{}    run:\n        _tophat_default()\n\n",
            list(&results).replace("        ", "    "),
            list(&results)
        ));
    }
    for (variant, all, _) in &variant_records {
        out.push_str(&format!(
            "rule {}:\n    input:\n{}\n",
            variant_target(variant, trial),
            list(all)
        ));
    }

    let qc_list = |qc: &[(String, String, String)]| {
        let items: Vec<String> = qc
            .iter()
            .map(|(s, k, v)| format!("({}, {}, {})", py(s), py(k), py(v)))
            .collect();
        format!("[{}]", items.join(", "))
    };
    for job in &jobs {
        let name = rule_name(&job.stage, &job.key, trial);
        let record = job.out_dir.join(RECORD_FILE);
        let inputs: String = job
            .inputs
            .iter()
            .map(|p| format!("        ancient({}),\n", pattern(p)))
            .collect();
        let input_block = if inputs.is_empty() {
            String::new()
        } else {
            format!("    input:\n{inputs}")
        };
        let trial_arg = if trial { ", trial=True" } else { "" };
        let external_arg = if job.external { ", external=True" } else { "" };
        let job_args = format!(
            "{}, {}, {}{trial_arg}, qc={}{external_arg}",
            py(&job.stage),
            py(&job.key),
            py(&job.variant),
            qc_list(&job.qc)
        );
        // rq-4acafba4
        // An external job only writes or ingests its job folder locally.
        let threads = if job.external { 1 } else { job.threads };
        match &job.fan_out {
            None => {
                let kind = if checkpoints.contains(&(job.stage.clone(), job.key.clone())) {
                    "checkpoint"
                } else {
                    "rule"
                };
                out.push_str(&format!(
                    "{kind} {name}:\n{input_block}    output:\n        {}\n    threads: {threads}\n    run:\n        _tophat_job({job_args})\n\n",
                    pattern(&record),
                ));
            }
            Some(source) => {
                let item_pattern = py(&format!(
                    "{}/items/{{item}}/{RECORD_FILE}",
                    job.out_dir
                        .display()
                        .to_string()
                        .replace('{', "{{")
                        .replace('}', "}}")
                ));
                out.push_str(&format!(
                    "rule {name}_item:\n{input_block}    output:\n        {item_pattern}\n    wildcard_constraints:\n        item=\"[A-Za-z0-9._-]+\"\n    threads: {}\n    run:\n        _tophat_job({job_args}, item=wildcards.item)\n\n",
                    job.threads
                ));
                let items_expr = match source {
                    ItemSource::Checkpoint { rule, dir } => format!(
                        "_tophat_checkpoint_items(checkpoints.{rule}, {})",
                        py(&dir.display().to_string())
                    ),
                    ItemSource::Static(names) => format!(
                        "[{}]",
                        names.iter().map(|n| py(n)).collect::<Vec<_>>().join(", ")
                    ),
                };
                let kind = if checkpoints.contains(&(job.stage.clone(), job.key.clone())) {
                    "checkpoint"
                } else {
                    "rule"
                };
                let seal_trial = if trial { ", \"--trial\"" } else { "" };
                out.push_str(&format!(
                    "{kind} {name}:\n    input:\n        lambda wildcards: [{} + \"/items/\" + item + \"/{RECORD_FILE}\" for item in {items_expr}],\n    output:\n        {}\n    run:\n        _tophat(\"stage\", \"seal\", _TOPHAT_STUDY, {}, \"--key\", {}, \"--variant\", {}{seal_trial})\n\n",
                    py(&job.out_dir.display().to_string()),
                    pattern(&record),
                    py(&job.stage),
                    py(&job.key),
                    py(&job.variant)
                ));
            }
        }
    }
    Ok(out)
}

/// Project-relative path of a study's `Snakefile`.
pub fn snakefile_path(study: &str) -> String {
    format!("{STUDIES_DIR}/{study}/Snakefile")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test] // rq-fbc524b4 rq-3c19a18d
    fn stub_text() {
        let s = stub("x-vs-docking");
        assert!(s.contains("\"tophat\", \"pipeline\", \"rules\", \"x-vs-docking\""));
        assert!(s.contains("\"x-vs-docking.smk\""));
        assert!(s.contains("include: str(_rules)\n"));
        assert!(s.ends_with("        _tophat_default()\n"));
    }

    #[test]
    fn names() {
        assert_eq!(
            rule_name("clean-up", "sk-00000000000000ab", false),
            "clean_up_00000000000000ab"
        );
        assert_eq!(rule_name("x", "sk-1", true), "trial_x_1");
        assert_eq!(variant_target("b3-lyp", false), "variant_b3_lyp");
        assert_eq!(pattern(Path::new("/a/{b}")), "\"/a/{{b}}\"");
    }
}
